KM_INCLUDED = {'100': 100, '350': 350, '500': 500, '650': 650, '850': 850, 'unlimited': 9999}
PACKAGE_DAYS = {'4h': 0, '1-2d': 2, '3-5d': 5, '6-10d': 10, '11-20d': 20, '21-29d': 29}
EXTRA_KM_PRICE = 0.21
VAT = 1.21
COMPANY = env.ref('base.main_company')

valid_from = fields.Date.today()
Rule = env['vehicle.pricing.rule'].sudo().with_context(active_test=False)
Category = env['fleet.vehicle.model.category'].sudo()

closed = created = 0
for code, prices in sorted(TARIFFS_2026.items()):
    category = Category.search([('name', '=like', 'Tipo %s - %%' % code)], limit=1)
    if not category:
        raise SystemExit('Missing category Tipo %s' % code)
    old = Rule.search([
        ('vehicle_category_id', '=', category.id), ('pricing_type', '=', 'standard'),
        ('valid_from', '<', valid_from), ('valid_until', '=', False),
    ])
    old.write({'valid_until': valid_from - timedelta(days=1)})
    closed += len(old)
    for key, price in prices.items():
        km_range, duration_range = key.split('|')
        if Rule.search_count([
            ('vehicle_category_id', '=', category.id), ('pricing_type', '=', 'standard'),
            ('km_range', '=', km_range), ('duration_range', '=', duration_range),
            ('valid_from', '=', valid_from),
        ]):
            continue
        Rule.create({
            'vehicle_category_id': category.id,
            'pricing_type': 'standard',
            'km_range': km_range,
            'duration_range': duration_range,
            'km_included': KM_INCLUDED[km_range],
            'package_days': PACKAGE_DAYS[duration_range],
            'price_per_unit': price,
            'price_without_vat': round(price / VAT, 2),
            'extra_km_price': EXTRA_KM_PRICE,
            'currency_id': COMPANY.currency_id.id,
            'company_id': COMPANY.id,
            'valid_from': valid_from,
            'notes': 'Tarifa 2026 V3 (Tarifas completas Pinveco JUN26)',
        })
        created += 1
env.cr.commit()
print('VALID_FROM', valid_from)
print('CLOSED_OLD', closed)
print('CREATED_2026', created)

